<?php
/** Proof — vocabulary, views, canned, knowledge, service levels, rules, metrics, ratings, time, dispatches, mail and the caller's own things; plus the guarded searches. */
require __DIR__ . '/lib.php';
$F = dated(); $W = world(); $T = $F['tickets']; $IT = $F['it'];
$owner = as_member(1); $lena = as_member(28);
$sorted = function (array $a) { sort($a); return $a; };
echo "1. get_vocabulary, ticket_transitions\n";
$d = tdata(27, 'get_vocabulary', []);
ok(count($d['statuses']) >= 6 && count($d['transitions']) >= 6 && isset($d['types'], $d['categories'], $d['tags'], $d['fields']) && $d['priorities'] === ['low', 'normal', 'high', 'urgent'] && in_array('awaiting_requester', $d['hold_reasons']) && in_array('duplicate', $d['resolution_codes']), 'everything at once: statuses, transitions, types, categories, tags, fields, priorities, hold reasons, resolution codes');
$d = tdata(27, 'get_vocabulary', ['part' => 'statuses']);
ok(array_keys($d) === ['statuses'] && array_unique(array_column($d['statuses'], 'category')) !== [] && array_filter($d['statuses'], fn ($s) => $s['key'] === 'pending' && $s['clock_runs'] === false) !== [], 'part=statuses; the pending clock does not run');
$d = tdata(27, 'get_vocabulary', ['q' => 'solved']);
ok(is_array($d) && count($d) >= 1 && isset($d[0]['status_id']) && $d[0]['label'] === 'Solved', '`q` alone resolves a status by name');
$cat = (int) one("INSERT INTO categories (name, requester_visible) VALUES ('SMOKE p4 internal-only category', false) RETURNING id");
$cat2 = (int) one("INSERT INTO categories (name, requester_visible) VALUES ('SMOKE p4 public category', true) RETURNING id");
$names = fn (int $m) => array_column(tdata($m, 'get_vocabulary', ['part' => 'categories'])['categories'], 'name');
ok(in_array('SMOKE p4 internal-only category', $names(27)) && !in_array('SMOKE p4 internal-only category', $names(26)) && in_array('SMOKE p4 public category', $names(26)), 'a requester sees the requester-visible categories only; support sees all');
$d = tdata(27, 'ticket_transitions', ['ticket_id' => $T['it5']]);
$byKey = array_column($d['moves'], null, 'key');
ok($d['from']['category'] === 'open' && isset($byKey['solved']) && in_array('resolution_code', $byKey['solved']['requires']) && $byKey['solved']['may'] === true && isset($byKey['pending']), 'it5 (open) may be solved (needs a resolution_code) and snoozed; Marco may do it');
$d = tdata(26, 'ticket_transitions', ['ticket_id' => $W['t_p1']]);
ok(array_filter($d['moves'], fn ($m) => $m['may']) === [], 'Priya on her own ticket: every move says may=false (she may not work it)');
ok(tool(26, 'ticket_transitions', ['ticket_id' => $T['it5']])['error'], 'a ticket she may not see: refused');
echo "2. Views and boards\n";
$d = tdata(27, 'find_views', []);
$keys = array_column($d['views'], 'system_key');
ok(in_array('mine', $keys) && in_array('triage', $keys) && in_array('team_board', $keys), 'the standard views');
$d = tdata(27, 'find_views', ['q' => 'triage']);
ok(is_array($d) && count($d) === 1 && isset($d[0]['view_id']) && stripos($d[0]['name'], 'triage') === 0, '`q` alone: a plain list (view_id, name)');
$d = tdata(27, 'find_views', ['layout' => 'board']);
ok(count($d['views']) >= 1 && !array_filter($d['views'], fn ($v) => $v['layout'] !== 'board'), 'layout=board');
$b = tdata(27, 'board_snapshot', ['system_key' => 'team_board']);
$cards = array_sum(array_column($b['columns'], 'count'));
ok($b['column_field'] === 'status' && count($b['columns']) >= 4 && $cards === $b['cards'] && $cards >= 5 && array_unique(array_column($b['columns'], 'column')) === array_column($b['columns'], 'column'), "team_board: status columns, $cards cards as Marco sees them");
ok(!array_filter(array_merge(...array_column($b['columns'], 'cards')), fn ($c) => $c['queue_id'] !== $IT), 'only IT\'s cards (his reach)');
$b2 = tdata(27, 'board_snapshot', ['system_key' => 'team_board', 'swimlane' => 'priority']);
ok($b2['swimlane'] === 'priority' && array_filter(array_merge(...array_column($b2['columns'], 'cards')), fn ($c) => $c['lane'] !== null) !== [], 'swimlane=priority overrides the view');
ok(tool(27, 'board_snapshot', [])['error'] && tool(27, 'board_snapshot', ['system_key' => 'nope'])['error'], 'no view / an unknown view: refused');
echo "3. Canned responses and the knowledge base\n";
q("INSERT INTO canned_responses (title, folder, body_text, scope, queue_id, usage_count) VALUES ('SMOKE p4 Reset password', 'SMOKE p4', 'Hello {{requester.first_name}}, here is how to reset your password.', 'queue', :q, 3)", ['q' => $IT]);
q("INSERT INTO canned_responses (title, folder, body_text, scope, owner_member_id) VALUES ('SMOKE p4 Marco private', 'SMOKE p4', 'only mine', 'personal', 27)");
$d = tdata(27, 'search_canned_responses', ['q' => 'reset']);
ok(is_array($d) && $d === [['canned_id' => $d[0]['canned_id'], 'title' => 'SMOKE p4 Reset password']], '`q` alone: a plain list (canned_id, title)');
$d = tdata(27, 'search_canned_responses', ['folder' => 'SMOKE p4']);
ok(count($d['responses']) === 2 && str_contains($d['responses'][0]['body_text'], '{{requester.first_name}}'), 'the text with its placeholders');
$d = tdata(28, 'search_canned_responses', ['folder' => 'SMOKE p4']);
ok(count($d['responses']) === 1, "another person's private response is not visible (Lena sees the queue one only)");
ok(tdata(26, 'search_canned_responses', ['folder' => 'SMOKE p4'])['responses'] === [], 'a requester sees no canned responses');
$a = [];
foreach ([['SMOKE p4 Public VPN guide', 'public', 'published', 'Connect to the SMOKEvpn with the zebra client.'], ['SMOKE p4 Staff runbook', 'internal', 'published', 'The runbook mentions the giraffe safe.'], ['SMOKE p4 Draft guide', 'public', 'draft', 'A draft about the pelican tray.']] as [$t, $vis, $st, $body]) {
    [$c, $b] = act($owner, '/kb/admin/save.php', ['title' => $t, 'body' => $body, 'visibility' => $vis, 'status' => $st, 'tags' => 'p4']);
    $a[$st . $vis] = (int) $b['record_id'];
}
$d = tdata(26, 'search_articles', ['q' => 'SMOKE p4']);
ok(is_array($d) && count($d) === 2 && !array_filter($d, fn ($x) => str_contains($x['title'], 'Draft')), 'a requester (kb.read) sees published articles, public and internal — never a draft; `q` alone is a plain list');
$d = tdata(28, 'search_articles', ['q' => 'SMOKE p4', 'status' => 'draft']);
ok(isset($d['articles']) && count($d['articles']) === 1 && $d['articles'][0]['status'] === 'draft', 'Lena (kb.edit) asks for drafts');
$d = tdata(26, 'search_articles', ['q' => 'SMOKE p4', 'status' => 'draft']);
ok(isset($d['articles']) && count($d['articles']) === 2 && !array_filter($d['articles'], fn ($x) => $x['status'] === 'draft'), 'and Priya asking for drafts gets the published ones only — a draft never');
$d = tdata(26, 'search_articles', ['article_id' => $a['publishedpublic']]);
ok(str_contains($d['article']['body_text'], 'zebra client') && $d['article']['visibility'] === 'public', 'one article in full by id');
$d = tdata(26, 'search_articles', ['slug' => 'smoke-p4-public-vpn-guide']);
ok(($d['article']['article_id'] ?? 0) === $a['publishedpublic'], 'by slug');
ok(tool(26, 'search_articles', ['article_id' => $a['draftpublic']])['error'], 'a draft by id to a requester: not found');
$d = tdata(26, 'search_articles', ['tag' => 'x'] === [] ? [] : ['q' => 'zebra', 'visibility' => 'public']);
ok(isset($d['articles']) && count($d['articles']) === 1 && isset($d['sections']), 'with filters: the articles (excerpt) and the sections');
echo "4. Service levels and rules\n";
$d = tdata(27, 'find_sla_policies', []);
ok(count($d['policies']) >= 1 && $d['policies'][0]['name'] === 'Standard' && isset($d['policies'][0]['targets']['urgent']['first_response']) && isset($d['business_hours']), 'policies with per-priority targets, and the schedules');
$d = tdata(27, 'find_sla_policies', ['q' => 'stand']);
ok(is_array($d) && count($d) === 1 && $d[0]['name'] === 'Standard', '`q` alone: a plain list');
$d = tdata(27, 'find_rules', ['with_stats' => true]);
ok(count($d['rules']) === 2 && isset($d['rules'][0]['last_30_days']) && in_array('time_based', array_column($d['rules'], 'kind')), 'find_rules: the two seeded rules with stats');
$d = tdata(27, 'find_rules', ['q' => 'reopen']);
ok(is_array($d) && count($d) === 1, '`q` alone: a plain list (rule_id, name)');
q("INSERT INTO rule_runs (rule_id, ticket_id, outcome, detail) VALUES (1, :t, 'applied', '{\"actions\":[\"transition\"]}'), (1, :t, 'skipped', '{}'), (2, :t2, 'error', '{\"error\":\"boom\"}')", ['t' => $T['it1'], 't2' => $T['it5']]);
$d = tdata(27, 'rule_runs', ['rule_id' => 1]);
ok(count($d['runs']) === 2 && $d['runs'][0]['rule_name'] !== null, 'rule_runs by rule');
$d = tdata(27, 'rule_runs', ['ticket_id' => $T['it5'], 'outcome' => 'error']);
ok(count($d['runs']) === 1 && $d['runs'][0]['detail']['error'] === 'boom', 'by ticket and outcome; the detail decoded');
$d = tdata(27, 'find_rules', ['with_stats' => true]);
ok(($d['rules'][0]['last_30_days'] ?? []) !== [] , 'and the stats count the runs');
ok(tdata(26, 'find_rules', [])['rules'] === [] && tdata(26, 'rule_runs', [])['runs'] === [] && tdata(26, 'find_sla_policies', [])['policies'] === [], 'a requester sees no rules, no runs, no policies');
echo "5. Metrics, CSAT, time\n";
$P = sixty(); $from = (new DateTimeImmutable('-70 days'))->format('Y-m-d'); $to = (new DateTimeImmutable())->format('Y-m-d');
[$c, $php] = screen($lena, '/reports/volume?' . http_build_query(['from' => $from, 'to' => $to, 'group_by' => 'queue']));
[$c2, $phpFr] = screen($lena, '/reports/first_response?' . http_build_query(['from' => $from, 'to' => $to, 'group_by' => 'queue']));
[$c3, $phpSla] = screen($lena, '/reports/sla_attainment?' . http_build_query(['from' => $from, 'to' => $to, 'group_by' => 'queue']));
[$c4, $phpCs] = screen($lena, '/reports/csat?' . http_build_query(['from' => $from, 'to' => $to, 'group_by' => 'queue']));
[$c5, $phpRe] = screen($lena, '/reports/reopen_rate?' . http_build_query(['from' => $from, 'to' => $to, 'group_by' => 'queue']));
$m = tdata(28, 'metrics_summary', ['from' => $from, 'to' => $to]);
$s = $m['summary'];
$tot = $php['totals'];
ok($s['created'] === cell_int($tot[1]) && $s['solved'] === cell_int($tot[2]) && $s['closed'] === cell_int($tot[3]) && $s['reopened'] === cell_int($tot[4]), "metrics_summary = the PHP report's totals: created {$s['created']}, solved {$s['solved']}, closed {$s['closed']}, reopened {$s['reopened']}");
ok($s['responded'] === cell_int($phpFr['totals'][2]), 'responded = the first-response report\'s');
$sla = $s['sla'];
$due = $phpSla['totals'][2]; $met = $phpSla['totals'][3]; $br = $phpSla['totals'][4];
ok(array_sum(array_column($sla, 'due')) === cell_int($due) && array_sum(array_column($sla, 'met')) === cell_int($met) && array_sum(array_column($sla, 'breached')) === cell_int($br), "SLA due/met/breached = the report's ($due · $met · $br)");
ok($s['csat']['sent'] === cell_int($phpCs['totals'][1]) && $s['csat']['answered'] === cell_int($phpCs['totals'][2]) && $s['csat']['good'] === cell_int($phpCs['totals'][4]) && $s['csat']['bad'] === cell_int($phpCs['totals'][5]), 'CSAT sent/answered/good/bad = the report\'s');
ok($s['reopen_rate_pct'] === round($s['reopened'] * 100 / $s['solved'], 1), 'reopen rate = reopened / solved');
$itRow = array_values(array_filter($m['by_queue'], fn ($q) => $q['queue_id'] === $IT))[0];
$phpIt = array_values(array_filter($php['rows'], fn ($r) => $r[0] === 'SMOKE IT help'))[0];
ok($itRow['created'] === cell_int($phpIt[1]) && count($m['by_queue']) >= 3, "by queue: IT's created = the report's (" . $itRow['created'] . ')');
ok(isset($m['previous']['summary']['created']) && $m['period']['from'] === $from, 'the period before, of the same length');
$m2 = tdata(28, 'metrics_summary', ['period' => 'last_30_days', 'compare' => false, 'queue_id' => $IT]);
ok(!isset($m2['previous']) && $m2['queue_id'] === $IT && count($m2['by_queue']) === 1, 'compare=false, one queue');
$m3 = tdata(27, 'metrics_summary', ['from' => $from, 'to' => $to]);
ok(count($m3['by_queue']) === 1 && $m3['by_queue'][0]['queue_id'] === $IT && $m3['summary']['created'] === $itRow['created'], 'Marco (a holder, no reports.view): his queue only, the same IT numbers');
ok(tool(26, 'metrics_summary', [])['error'] && tool(28, 'metrics_summary', ['from' => '2026-02-01', 'to' => '2026-01-01'])['error'], 'a requester: "You may not see reports."; a backwards period: refused');
$d = tdata(28, 'csat_summary', ['from' => $from, 'to' => $to]);
ok($d['scale'] === 'good_bad' && $d['totals']['sent'] === 4 && $d['totals']['answered'] === 3 && $d['totals']['good'] === 2 && $d['totals']['bad'] === 1 && $d['totals']['good_pct'] === 66.7 && count($d['ratings']) === 3 && $d['trend'] !== [], 'csat_summary: 4 sent, 3 answered, 2 good, 1 bad (66.7%), the ratings and a weekly trend');
$d = tdata(28, 'csat_summary', ['from' => $from, 'to' => $to, 'score' => 'bad']);
ok(count($d['ratings']) === 1 && $d['ratings'][0]['bad_reason'] === 'slow' && $d['ratings'][0]['number'] === num_of($T['it2']), 'score=bad: the bad one, its reason, its ticket');
ok(tdata(26, 'csat_summary', ['from' => $from, 'to' => $to])['totals']['sent'] === 0, 'a requester sees none of the dated ratings');
$d = tdata(27, 'time_entries', ['ticket_id' => $T['it1']]);
ok($d['minutes'] === 90 && $d['billable_minutes'] === 90 && $d['entries'][0]['display_name'] === 'SMOKE Marco', 'time_entries on a ticket: 90 minutes, billable');
$d = tdata(27, 'time_entries', ['member_id' => 27]);
ok($d['minutes'] === 120 && count($d['entries']) === 2, "by person: Marco's 120 minutes");
$d = tdata(27, 'time_entries', ['member_id' => 27, 'from' => (new DateTimeImmutable('-10 days'))->format('Y-m-d')]);
ok($d['minutes'] === 30, 'from a date: the recent 30');
ok(tdata(26, 'time_entries', [])['entries'] === [], 'a requester sees no time');
echo "6. Dispatches, mail, notifications, tokens\n";
q("INSERT INTO agent_dispatches (ticket_id, agent_member_id, kind, via, acting_member_id, status, reply_excerpt) VALUES (:t, 40, 'assigned', 'chat', 27, 'answered', 'SMOKE p4 done')", ['t' => $T['it5']]);
$d = tdata(27, 'agent_dispatches', ['ticket_id' => $T['it5']]);
ok(count($d['dispatches']) === 1 && $d['dispatches'][0]['agent_name'] === 'SMOKE Frontline' && $d['dispatches'][0]['status'] === 'answered', 'agent_dispatches: what was handed to Frontline');
ok(tdata(26, 'agent_dispatches', [])['dispatches'] === [], 'a requester sees none');
q("INSERT INTO mailboxes (address, display_name, queue_id) VALUES ('p4support@example.invalid', 'SMOKE p4 box', :q)", ['q' => $IT]);
$mb = (int) one("SELECT id FROM mailboxes WHERE address = 'p4support@example.invalid'");
q("INSERT INTO inbound_email (mailbox_id, message_id, from_address, subject, status, error) VALUES (:m, '<p4@x>', 'who@customer.invalid', 'SMOKE p4 bounced', 'failed', 'parse error')", ['m' => $mb]);
$d = tdata(1, 'find_mailboxes', ['failures_only' => true]);
ok(count($d['mailboxes']) >= 1 && count($d['inbound']) === 1 && $d['inbound'][0]['error'] === 'parse error', 'find_mailboxes as the owner: the box and the failed mail with its error');
$d = tdata(1, 'find_mailboxes', ['q' => 'p4support']);
ok(is_array($d) && count($d) === 1 && isset($d[0]['mailbox_id']), '`q` alone: a plain list (mailbox_id, address)');
$d = tdata(26, 'find_mailboxes', []);
ok(($d['mailboxes'] ?? []) === [] && ($d['inbound'] ?? []) === [], 'a requester sees no mailboxes and no mail');
q("INSERT INTO notifications (member_id, kind, ticket_id, title, body) VALUES (27, 'assigned', :t, 'SMOKE p4 assigned to you', 'x'), (26, 'replied', :t2, 'SMOKE p4 priya only', 'y')", ['t' => $T['it5'], 't2' => $mine ?? $W['t_p1']]);
$d = tdata(27, 'my_notifications', ['unread_only' => true]);
ok(count($d['notifications']) === 1 && $d['notifications'][0]['title'] === 'SMOKE p4 assigned to you', 'my_notifications: his own, not Priya\'s');
$d = tdata(27, 'my_tokens', []);
ok(count($d['tokens']) >= 1 && !has_key($d, 'token_hash') && !has_key($d, 'token') && $d['tokens'][0]['scope'] === 'mcp', 'my_tokens: label and scope, never the value');
echo "7. The guarded searches\n";
$d = tdata(27, 'records_search', ['sql' => "select number, status_category from mcp_tickets where queue_id = $IT order by number limit 3"]);
ok(is_array($d) && count($d) === 3 && isset($d[0]['number']), 'records_search: a SELECT over the views');
$d = tdata(26, 'records_search', ['sql' => 'select count(*) as n from mcp_tickets']);
ok($d[0]['n'] === count(sql_as(26, 'select 1 from mcp_tickets')), 'scoped to the caller (Priya counts her own)');
foreach (['delete from tickets' => 'Only a single SELECT', 'select 1; select 2' => 'Only one statement', "select set_config('app.member_id','1',true)" => 'set_config', "select current_setting('app.member_id')" => 'current_setting', "select mcp_admit_agent(1)" => 'mcp_admit_agent',
          "select hd_secure_link_ticket('x')" => 'hd_secure_link_', "select hd_requester_for_email('a@b.c')" => 'hd_requester_for_', 'select pg_sleep(1)' => 'pg_', "select * from tickets" => 'Query failed', "select * from mcp_access_tokens" => 'Query failed', "select 1 union select 2 -- update x" => 'Only read queries'] as $sql => $why) {
    $r = tool(27, 'records_search', ['sql' => $sql]);
    ok($r['error'] || str_contains($r['text'], $why), "records_search refuses: " . substr($sql, 0, 48) . " ($why)");
}
$d = tdata(27, 'records_search', ['sql' => 'select generate_series(1, 500) as n']);
ok(count($d) === 200, 'rows capped at 200');
$r = tool(27, 'records_search', ['sql' => 'select pg_sleep(8)']);
ok($r['error'], 'pg_ calls are refused before they can run long');
finish();
